mapper.select:
SELECT  FROM reading_subscription_mandate
WHERE user_id=#{userId} AND client_request_id=#{clientRequestId}
LIMIT 1

SELECT id FROM reading_subscription_mandate
WHERE status='REVOKE_PENDING' AND revoke_next_attempt_at<=#{now}
  AND (revoke_lease_until IS NULL OR revoke_lease_until<=#{now})
ORDER BY revoke_next_attempt_at, id
LIMIT #{limit}
